<?php $__currentLoopData = ($flags ?? []); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $f): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><span class="status <?php echo e(in_array($f, ['ABSENT', 'MISSING_IN', 'MISSING_OUT']) ? 'status-cancelled' : (in_array($f, ['LATE', 'EARLY_OUT']) ? 'status-on-hold' : 'status-in-progress')); ?>"><?php echo e(config('hr.attendance.flags')[$f] ?? $f); ?></span> <?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?>
